import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;

  bool _hasMore = true;

  bool _isLoadingNextPage = false;

  Future<void>? _initialLoadFuture;

  @override
  void initState() {
    super.initState();
    _filteredCurrenciesNotifier = ValueNotifier(const []);
    _loadInitialData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    super.dispose();
  }

  Future<void> _loadInitialData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currentPage = 0;
      _allCurrencies = [];
      _hasMore = true;
      _isLoadingNextPage = false;
      _filteredCurrenciesNotifier.value = const [];
    });

    _initialLoadFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then((CurrencyPage page) {
      final List<CurrencyModel> items = page.items;

      setState(() {
        _allCurrencies = items;
        _filteredCurrenciesNotifier.value = items;
        _currentPage = page.page;
        _hasMore = page.hasMore;
      });

      currencyRepository.saveCurrencyList(items);
    }).catchError((Object error, StackTrace stack) {
      debugPrint('Failed to load initial data: $error');
    });
  }

  /// Вызывается при возврате на экран для обновления свежими данными.
  void refreshData() {
    _initialLoadFuture = null;
    _loadInitialData();
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingNextPage || !_hasMore) return;

    setState(() => _isLoadingNextPage = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = _currentPage + 1;

    try {
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: 20));

      setState(() {
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        _currentPage = page.page;
        _hasMore = page.hasMore;
        _isLoadingNextPage = false;

        currencyRepository.saveCurrencyList(page.items);
      });
    } catch (error, stack) {
      debugPrint('Failed to load next page: $error');
      setState(() => _isLoadingNextPage = false);
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initialLoadFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                child: SearchView(onChanged: _filterCurrencies),
              ),
              Expanded(
                child: ValueListenableBuilder<List<CurrencyModel>>(
                  valueListenable: _filteredCurrenciesNotifier,
                  builder: (BuildContext context, List<CurrencyModel> data, _) {
                    return ListView.builder(
                      itemCount: data.length + (_hasMore ? 1 : 0),
                      itemBuilder: (BuildContext context, int index) {
                        if (index >= data.length) {
                          // Кнопка «Показать ещё» — показывается только если есть следующие страницы
                          if (_isLoadingNextPage) {
                            return const Padding(
                              padding: EdgeInsets.all(16.0),
                              child: Center(child: CircularProgressIndicator()),
                            );
                          }

                          return Padding(
                            padding: const EdgeInsets.all(16.0),
                            child: SizedBox(
                              width: double.infinity,
                              child: ElevatedButton(
                                onPressed: _loadNextPage,
                                child: Text(loc.showMore),
                              ),
                            ),
                          );
                        }

                        final CurrencyModel currency = data[index];

                        return Padding(
                          key: ValueKey(currency.id),
                          padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                          child: CurrencyCard(model: currency),
                        );
                      },
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

