class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  late final GlobalKey<CurrencyListPageState> _currencyListKey;

  static const List<Widget> _pages = <Widget>[
    NewsListPage(),
    ProfilePage(),
  ];

  @override
  void initState() {
    super.initState();
    _currencyListKey = GlobalKey<CurrencyListPageState>();
  }

  void _onItemTapped(int index) {
    final int previousIndex = _selectedIndex;
    setState(() {
      _selectedIndex = index;
    });

    // При возврате на вкладку валют — обновить данные свежим запросом
